// Используем объект, массив, let/const, цикл и условие по требованиям лабы
const student = { name: "Ульяна Казак", group: "УИР-241" };
let numbers = [5, 12, 8, 20, 15];
let sum = 0;

// Цикл for для подсчета суммы элементов
for (let i = 0; i < numbers.length; i++) {
    sum += numbers[i];
}

// Условие if/else
let statusText = "";
if (sum > 50) {
    statusText = "Успешно";
} else {
    statusText = "Требует внимания";
}

// Возвращаем объект с полем payload (требование пункта 2.2)
return [{
    json: {
        payload: {
            studentInfo: student,
            numbersArray: numbers,
            totalSum: sum,
            status: statusText,
            timestamp: new Date().toISOString()
        }
    }
}];
